// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;

    function setUp() public { c = new ERCDDAToken(0, "", ""); }

    function testFuzz_property(address target, uint256 amount) public {
        vm.assume(target != address(0));
        amount = bound(amount, 1, type(uint256).max);

        uint256 supplyBefore = c.totalSupply();
        address owner = c.owner();

        vm.prank(owner);
        c.mintToken(target, amount);

        assertTrue(
            c.totalSupply() == supplyBefore + amount &&
            c.balanceOf(target) == amount,
            "minting must increase totalSupply and credit the target"
        );
    }
}
